import net.neoforged.neoforge.event.AddPackFindersEvent;
import net.neoforged.neoforge.data.event.GatherDataEvent;
import net.neoforged.neoforge.common.NeoForge;

// Add custom data pack
NeoForge.EVENT_BUS.addListener((AddPackFindersEvent event) -> {
    event.addDataPackFinders(modResourceManager, ResourceType.SERVER_DATA, "mymod");
});

// Data generation
NeoForge.EVENT_BUS.addListener((GatherDataEvent event) -> {
    if (event.includeServer()) {
        event.getGenerator().addProvider(true, new MyRecipeProvider(event.getGenerator().getPackOutput()));
    }
});
